 const [datasetId,setDatasetId]=useState(''),[modelId,setModelId]=useState(''),[inferenceId,setInferenceId]=useState(''),[attackType,setAttackType]=useState('TRIGGER'),[rate,setRate]=useState(5),[seed,setSeed]=useState('47321'),[currentId,setCurrentId]=useState(''),[caseId,setCaseId]=useState(''),[note,setNote]=useState(''),[disposition,setDisposition]=useState('QUARANTINE');
