 const filtered=(items:E[])=>items.filter(e=>(!search||JSON.stringify([e.id,e.name,e.title,e.detector]).toLowerCase().includes(search.toLowerCase()))&&(filter==='ALL'||e.disposition===filter||e.severity===filter));
 useEffect(()=>{if(!datasetId&&datasets.length)setDatasetId(datasets[datasets.length-1].id);if(!modelId&&models.length)setModelId(models[models.length-1].id);if(!inferenceId&&inferences.length)setInferenceId(inferences[0].id);if(!caseId&&cases.length)setCaseId(cases[0].id);},[state,datasetId,modelId,inferenceId,caseId]);
